def linear_getViewer(org_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "linear_getViewer"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, org=None, detail=None):
        logs = _load("linear_request_log.json")
        row = {
            "id": f"lin_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "org_id": org_id if isinstance(org_id, str) else None,
            "resolved_org_id": org.get("id") if isinstance(org, dict) else None,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - start) * 1000),
            "created_at": _now(),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("linear_request_log.json", logs)

    # Validate
    if not isinstance(org_id, str) or not re.match(r"^lin_org_[0-9A-HJKMNP-TV-Z]{16,}$", org_id):
        _log("error", None, "VALIDATION_ERROR: invalid org_id")
        return _err("VALIDATION_ERROR", "org_id is missing or invalid", field="org_id")

    orgs = _load("linear_org.json")
    org = next((o for o in orgs if o.get("id") == org_id), None)
    if not org:
        _log("error", None, "NOT_FOUND: org not found")
        return _err("NOT_FOUND", "Organization not found", org_id=org_id)

    if org.get("status") != "active":
        _log("error", org, "UNAUTHORIZED: org not active")
        return _err("UNAUTHORIZED", "Organization connection is not active", org_status=org.get("status"))

    users = _load("linear_users.json")

    def _gen_id(prefix):
        # pseudo-crockford base32-ish id body
        body = base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("=").replace("O", "0").replace("I", "1").upper()
        body = re.sub(r"[^0-9A-Z]", "", body)
        return f"{prefix}{body}"

    viewer_id = org.get("viewer_user_id")
    viewer = None
    if isinstance(viewer_id, str):
        viewer = next((u for u in users if u.get("id") == viewer_id), None)

    # If viewer missing, resolve/create one "from upstream" (offline): pick an existing active user in org, else create.
    if not viewer:
        viewer = next((u for u in users if u.get("org_id") == org_id and u.get("status") == "active" and u.get("is_active") is True), None)
        if not viewer:
            now = _now()
            viewer = {
                "id": _gen_id("lin_usr_"),
                "org_id": org_id,
                "linear_user_id": _gen_id("linu_"),
                "display_name": "Viewer",
                "email": None,
                "is_active": True,
                "is_admin": False,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            # enforce unique(org_id, linear_user_id) and unique(org_id,email where not null)
            if any(u.get("org_id") == org_id and u.get("linear_user_id") == viewer["linear_user_id"] for u in users):
                # extremely unlikely; treat as conflict
                _log("error", org, "CONFLICT: generated linear_user_id collision")
                return _err("CONFLICT", "Could not create viewer due to id collision")
            users.append(viewer)
            _save("linear_users.json", users)

        # update org.viewer_user_id
        org["viewer_user_id"] = viewer["id"]
        org["updated_at"] = _now()
        for i, o in enumerate(orgs):
            if o.get("id") == org_id:
                orgs[i] = org
                break
        _save("linear_org.json", orgs)

    # FORBIDDEN if viewer not member of org
    if viewer.get("org_id") != org_id:
        _log("error", org, "UNAUTHORIZED/FORBIDDEN: viewer not member of org")
        return _err("UNAUTHORIZED", "No authenticated viewer is available for this organization")

    # If viewer is deleted/disabled, treat as unauthorized
    if viewer.get("status") != "active" or viewer.get("is_active") is not True:
        _log("error", org, "UNAUTHORIZED: viewer inactive")
        return _err("UNAUTHORIZED", "No authenticated viewer is available", viewer_status=viewer.get("status"))

    _log("ok", org, None)
    return {
        "organization": org,
        "viewer": viewer,
        "membership": {
            "org_id": org_id,
            "user_id": viewer.get("id"),
            "is_active": viewer.get("is_active"),
            "is_admin": viewer.get("is_admin"),
            "status": viewer.get("status"),
        },
    }

def linear_getOrganization(org_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
