            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "linear_getOrganization"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, org=None, detail=None):
        logs = _load("linear_request_log.json")
        row = {
            "id": f"lin_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "org_id": org_id if isinstance(org_id, str) else None,
            "resolved_org_id": org.get("id") if isinstance(org, dict) else None,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - start) * 1000),
            "created_at": _now(),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("linear_request_log.json", logs)

    if not isinstance(org_id, str) or not re.match(r"^lin_org_[0-9A-HJKMNP-TV-Z]{16,}$", org_id):
        _log("error", None, "VALIDATION_ERROR: invalid org_id")
        return _err("VALIDATION_ERROR", "org_id is missing or invalid", field="org_id")

    orgs = _load("linear_org.json")
    org = next((o for o in orgs if o.get("id") == org_id), None)
    if not org:
        _log("error", None, "NOT_FOUND: org not found")
        return _err("NOT_FOUND", "Organization not found", org_id=org_id)

    # Reads must scope by a single active org; if not active -> authorization/connection error.
    if org.get("status") != "active":
        _log("error", org, "UNAUTHORIZED: org not active")
        return _err("UNAUTHORIZED", "Organization connection is not active", org_status=org.get("status"))

    # Ambient auth: ensure we can resolve a viewer member for this org; otherwise unauthorized.
    users = _load("linear_users.json")
    viewer_id = org.get("viewer_user_id")
    viewer = next((u for u in users if viewer_id and u.get("id") == viewer_id), None)
    if not viewer:
        viewer = next((u for u in users if u.get("org_id") == org_id and u.get("status") == "active" and u.get("is_active") is True), None)
    if not viewer or viewer.get("org_id") != org_id:
        _log("error", org, "UNAUTHORIZED: no viewer member")
        return _err("UNAUTHORIZED", "Not authorized to read this organization")

    _log("ok", org, None)
    return {"organization": org}

def linear_getUsers(org_id, status=None, is_active=None, is_admin=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "linear_getUsers"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, org=None, detail=None):
        logs = _load("linear_request_log.json")
        row = {
            "id": f"lin_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "org_id": org_id if isinstance(org_id, str) else None,
            "resolved_org_id": org.get("id") if isinstance(org, dict) else None,
            "status": status_s,
            "detail": detail,
            "latency_ms": int((time.time() - start) * 1000),
            "created_at": _now(),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("linear_request_log.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Validate org_id
    if not isinstance(org_id, str) or not re.match(r"^lin_org_[0-9A-HJKMNP-TV-Z]{16,}$", org_id):
        _log("error", None, "VALIDATION_ERROR: invalid org_id")
        return _err("VALIDATION_ERROR", "org_id is missing or invalid", field="org_id")

    # Validate filters
    if status is not None and status not in ("active", "disabled", "deleted"):
        _log("error", None, "VALIDATION_ERROR: invalid status")
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status")
    if is_active is not None and not isinstance(is_active, bool):
        _log("error", None, "VALIDATION_ERROR: is_active type")
        return _err("VALIDATION_ERROR", "is_active must be boolean", field="is_active")
    if is_admin is not None and not isinstance(is_admin, bool):
        _log("error", None, "VALIDATION_ERROR: is_admin type")
        return _err("VALIDATION_ERROR", "is_admin must be boolean", field="is_admin")
    if search is not None and not isinstance(search, str):
        _log("error", None, "VALIDATION_ERROR: search type")
        return _err("VALIDATION_ERROR", "search must be string", field="search")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", None, "VALIDATION_ERROR: limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "display_name", "email"):
        _log("error", None, "VALIDATION_ERROR: sort")
        return _err("VALIDATION_ERROR", "Invalid sort field", field="sort")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", None, "VALIDATION_ERROR: order")
        return _err("VALIDATION_ERROR", "Invalid order", field="order")

    # Resolve org and auth precondition
    orgs = _load("linear_org.json")
    org = next((o for o in orgs if o.get("id") == org_id), None)
    if not org:
        _log("error", None, "NOT_FOUND: org not found")
        return _err("NOT_FOUND", "Organization not found", org_id=org_id)
    if org.get("status") != "active":
        _log("error", org, "UNAUTHORIZED: org not active")
        return _err("UNAUTHORIZED", "Organization connection is not active", org_status=org.get("status"))

    users = _load("linear_users.json")
    viewer_id = org.get("viewer_user_id")
    viewer = next((u for u in users if viewer_id and u.get("id") == viewer_id), None)
    if not viewer:
        viewer = next((u for u in users if u.get("org_id") == org_id and u.get("status") == "active" and u.get("is_active") is True), None)
    if not viewer or viewer.get("org_id") != org_id:
        _log("error", org, "UNAUTHORIZED: no viewer member")
        return _err("UNAUTHORIZED", "Not authorized to read users for this organization")

    # Filter
    rows = [u for u in users if u.get("org_id") == org_id]
    if status is not None:
        rows = [u for u in rows if u.get("status") == status]
    if is_active is not None:
        rows = [u for u in rows if u.get("is_active") is is_active]
    if is_admin is not None:
        rows = [u for u in rows if u.get("is_admin") is is_admin]
    if search:
        q = search.strip().lower()
        if q:
            def _hay(u):
                return f"{u.get('display_name') or ''}\n{u.get('email') or ''}".lower()
            rows = [u for u in rows if q in _hay(u)]

    # Sort
    rev = (order == "desc")
    def _k(u):
        v = u.get(sort)
        if v is None:
            return ""
        return v
    rows.sort(key=_k, reverse=rev)

    # Pagination (cursor is opaque json: { "sort": ..., "order": ..., "after": { "value": ..., "id": ... } })
    after = None
    if cursor is not None:
        c = _decode_cursor(cursor)
        if not c or c.get("sort") != sort or c.get("order") != order or "after" not in c:
            _log("error", org, "VALIDATION_ERROR: malformed cursor")
            return _err("VALIDATION_ERROR", "Malformed cursor", field="cursor")
        after = c.get("after") or None

    if after:
        av = after.get("value")
        aid = after.get("id")
        def _is_after(u):
            uv = u.get(sort)
            uid = u.get("id")
            if order == "asc":
                if uv is None and av is None:
                    return (uid or "") > (aid or "")
                if uv is None:
                    return False
                if av is None:
                    return True
                if uv > av:
                    return True
                if uv == av and (uid or "") > (aid or ""):
                    return True
                return False
            else:
                if uv is None and av is None:
                    return (uid or "") < (aid or "")
                if uv is None:
                    return False
                if av is None:
                    return True
                if uv < av:
                    return True
                if uv == av and (uid or "") < (aid or ""):
                    return True
                return False
        rows = [u for u in rows if _is_after(u)]

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = None
    if page and has_more:
        last = page[-1]
        next_cursor = _encode_cursor({"sort": sort, "order": order, "after": {"value": last.get(sort), "id": last.get("id")}})

    _log("ok", org, None)
    return {
        "users": page,
        "page_info": {
            "limit": limit,
            "total": len([u for u in users if u.get("org_id") == org_id]),
            "returned": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

def linear_getLabels(org_id, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
