def linear_createProject(org_id, name, description=None, team_id=None, lead_user_id=None, status=None, start_date=None, target_date=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_s, used_org_id=None, details=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = _load("linear_request_log.json")
        req.append({
            "id": f"lin_req_{int(time.time()*1000)}",
            "endpoint": "linear_createProject",
            "org_id": used_org_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": now,
            "details": details or {}
        })
        _save("linear_request_log.json", req)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a date-time string.")
        try:
            # accept Z or offset; store normalized ISO with Z when naive/UTC
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(microsecond=0).isoformat() + "Z"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(microsecond=0).isoformat() + "Z"
        except Exception:
            raise ValueError(f"Invalid {field} format.")

    try:
        # ---- validate ----
        if not isinstance(org_id, str) or not re.match(r"^lin_org_[0-9A-HJKMNP-TV-Z]{16,}$", org_id):
            _log("error", org_id, {"reason": "bad_org_id"})
            return _err("VALIDATION_ERROR", "Malformed org_id.")
        if not isinstance(name, str) or len(name.strip()) < 1:
            _log("error", org_id, {"reason": "bad_name"})
            return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.")
        name = name.strip()
        if description is not None and not isinstance(description, str):
            _log("error", org_id, {"reason": "bad_description"})
            return _err("VALIDATION_ERROR", "description must be a string.")
        if team_id is not None and (not isinstance(team_id, str) or not team_id):
            _log("error", org_id, {"reason": "bad_team_id"})
            return _err("VALIDATION_ERROR", "team_id must be a non-empty string.")
        if lead_user_id is not None:
            if not isinstance(lead_user_id, str) or not re.match(r"^lin_usr_[0-9A-HJKMNP-TV-Z]{16,}$", lead_user_id):
                _log("error", org_id, {"reason": "bad_lead_user_id"})
                return _err("VALIDATION_ERROR", "Malformed lead_user_id.")
        if status is None:
            status = "planned"
        if status not in ("planned", "started", "paused", "completed", "canceled"):
            _log("error", org_id, {"reason": "bad_status"})
            return _err("VALIDATION_ERROR", "Invalid status.")
        try:
            start_iso = _parse_dt(start_date, "start_date")
            target_iso = _parse_dt(target_date, "target_date")
        except ValueError as ve:
            _log("error", org_id, {"reason": "bad_dates", "detail": str(ve)})
            return _err("VALIDATION_ERROR", str(ve))

        # ---- auth/connection context: must have active org ----
        orgs = _load("linear_org.json")
        org = next((o for o in orgs if o.get("id") == org_id), None)
        if not org:
            _log("error", org_id, {"reason": "org_not_found"})
            return _err("NOT_FOUND", "Organization not found.")
        if org.get("status") != "active":
            _log("error", org_id, {"reason": "org_not_active"})
            return _err("UNAUTHORIZED", "Organization connection is not active.")

        wss = _load("linear_workspaces.json")
        ws_idx = next((i for i, w in enumerate(wss) if w.get("org_id") == org_id), None)
        if ws_idx is None:
            _log("error", org_id, {"reason": "workspace_not_found"})
            return _err("NOT_FOUND", "Organization workspace projection not found.")
        ws = wss[ws_idx]

        # referenced entities must exist and belong to org
        if team_id is not None:
            if not any(t.get("id") == team_id for t in (ws.get("teams") or [])):
                _log("error", org_id, {"reason": "team_not_found"})
                return _err("NOT_FOUND", "Team not found for organization.")
        if lead_user_id is not None:
            users = _load("linear_users.json")
            u = next((x for x in users if x.get("id") == lead_user_id), None)
            if not u or u.get("org_id") != org_id:
                _log("error", org_id, {"reason": "lead_not_found"})
                return _err("NOT_FOUND", "Lead user not found for organization.")

        projects = ws.get("projects") or []

        # uniqueness: project name unique per org (case-sensitive in store; treat case-insensitive to be safe)
        for p in projects:
            if str(p.get("name", "")).strip().lower() == name.lower():
                _log("error", org_id, {"reason": "name_conflict"})
                return _err("CONFLICT", "A project with this name already exists in the organization.")

        # generate id
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _gen_id(prefix):
            import secrets
            return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

        new_project = {
            "id": _gen_id("lin_prj_"),
            "linear_project_id": _gen_id("lin_up_prj_"),
            "name": name,
            "description": description if description is not None else "",
            "status": status,
            "lead_user_id": lead_user_id,
            "start_date": start_iso,
            "target_date": target_iso,
            "created_at": now,
            "updated_at": now
        }

        projects.append(new_project)
        ws["projects"] = projects
        ws["updated_at"] = now
        wss[ws_idx] = ws
        _save("linear_workspaces.json", wss)

        _log("ok", org_id, {"project_id": new_project["id"]})
        return {"project": new_project}
    except (ValueError, TypeError):
        _log("error", org_id, {"reason": "unexpected_value"})
        return _err("VALIDATION_ERROR", "Invalid input.")
    except Exception as e:
        _log("error", org_id, {"reason": "internal", "detail": str(e)})
        return _err("CONFLICT", "Internal error.")

def linear_updateProject(projectId, data, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string")
        try:
            # accept 'Z'
            ss = s.replace("Z", "+00:00")
            datetime.datetime.fromisoformat(ss)
            return ss
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time")

    def _gen_cursor(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _audit(endpoint, status, org_id=None, viewer_user_id=None, meta=None, started=None):
        logs = _load("linear_audit_log.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": "lin_aud_" + hashlib.sha256((ts + endpoint + str(status) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26],
            "timestamp": ts,
            "endpoint": endpoint,
            "status": status,
            "org_id": org_id,
            "viewer_user_id": viewer_user_id,
            "latency_ms": latency_ms,
            "meta": meta or {}
        }
        logs.append(row)
        _save("linear_audit_log.json", logs)

    started = time.time()
    endpoint = "linear_updateProject"

    try:
        if not isinstance(projectId, str):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "projectId must be a string")
        if not re.match(r"^lin_prj_[0-9A-HJKMNP-TV-Z]{26}$", projectId):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "projectId is malformed")

        if not isinstance(data, dict):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "data must be an object")

        allowed_keys = {"name", "description", "status", "teamId", "startDate", "targetDate"}
        unknown = [k for k in data.keys() if k not in allowed_keys]
        if unknown:
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR", "unknown_fields": unknown}, started=started)
            return _err("VALIDATION_ERROR", "data contains unknown fields", unknown_fields=unknown)

        # Resolve an active org context (ambient auth); must be active
        orgs = _load("linear_org.json")
        if not isinstance(orgs, list):
            orgs = []
        active_orgs = [o for o in orgs if isinstance(o, dict) and o.get("status") == "active"]
        if not active_orgs:
            _audit(endpoint, "error", meta={"code": "UNAUTHORIZED"}, started=started)
            return _err("UNAUTHORIZED", "No active Linear organization connection")

        workspaces = _load("linear_workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        issues = _load("linear_issues.json")
        if not isinstance(issues, list):
            issues = []

        # Find the project in any active org workspace
        ws_row = None
        proj = None
        org = None
        for o in active_orgs:
            oid = o.get("id")
            if not isinstance(oid, str):
                continue
            for w in workspaces:
                if not isinstance(w, dict) or w.get("org_id") != oid:
                    continue
                projects = w.get("projects")
                if not isinstance(projects, list):
                    continue
                for p in projects:
                    if isinstance(p, dict) and p.get("id") == projectId:
                        ws_row = w
                        proj = p
                        org = o
                        break
                if proj is not None:
                    break
            if proj is not None:
                break

        if proj is None or ws_row is None or org is None:
            _audit(endpoint, "error", meta={"code": "NOT_FOUND"}, started=started)
            return _err("NOT_FOUND", "Project not found")

        viewer_user_id = org.get("viewer_user_id")

        # Validate fields
        if "name" in data:
            if data["name"] is None or not isinstance(data["name"], str) or not data["name"].strip():
                _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                       meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "name must be a non-empty string")
        if "description" in data and data["description"] is not None and not isinstance(data["description"], str):
            _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                   meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "description must be a string or null")

        # NOTE: tool schema status enum differs from stored project status enum.
        # We accept only the tool's enum per contract, and map:
        # active -> started (best fit), archived -> archived, deleted -> archived (no delete in project enum)
        status_map = {"active": "started", "archived": "archived", "deleted": "archived"}
        if "status" in data:
            if data["status"] not in ("active", "archived", "deleted"):
                _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                       meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")

        if "teamId" in data:
            teamId = data["teamId"]
            if teamId is None or not isinstance(teamId, str) or not re.match(r"^lin_team_[0-9A-HJKMNP-TV-Z]{26}$", teamId):
                _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                       meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "teamId is malformed")
            teams = ws_row.get("teams") if isinstance(ws_row.get("teams"), list) else []
            if not any(isinstance(t, dict) and t.get("id") == teamId for t in teams):
                _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                       meta={"code": "NOT_FOUND"}, started=started)
                return _err("NOT_FOUND", "Team not found")

        sd = td = None
        if "startDate" in data:
            r = _parse_dt(data["startDate"], "startDate")
            if isinstance(r, dict) and r.get("error"):
                _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                       meta={"code": "VALIDATION_ERROR"}, started=started)
                return r
            sd = r
        if "targetDate" in data:
            r = _parse_dt(data["targetDate"], "targetDate")
            if isinstance(r, dict) and r.get("error"):
                _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                       meta={"code": "VALIDATION_ERROR"}, started=started)
                return r
            td = r

        # Enforce unique(org_id, name) for projects when changing name
        if "name" in data:
            new_name = data["name"].strip()
            projects = ws_row.get("projects") if isinstance(ws_row.get("projects"), list) else []
            for p in projects:
                if not isinstance(p, dict):
                    continue
                if p.get("id") != projectId and p.get("name") == new_name:
                    _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                           meta={"code": "CONFLICT"}, started=started)
                    return _err("CONFLICT", "Project name must be unique within the organization")

        # Lifecycle rule: archived projects cannot be edited except unarchive if supported.
        # We interpret "archived" state in stored enum; allow only status change away from archived and no other edits.
        current_status = proj.get("status")
        intended_status = current_status
        if "status" in data:
            intended_status = status_map[data["status"]]

        if current_status == "archived":
            non_status_changes = any(k in data for k in ("name", "description", "teamId", "startDate", "targetDate"))
            if non_status_changes:
                # allow only if also unarchiving? spec says only unarchive if supported
                if not ("status" in data and intended_status != "archived"):
                    _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                           meta={"code": "INVALID_TRANSITION"}, started=started)
                    return _err("INVALID_TRANSITION", "Archived projects cannot be edited except unarchive")
            # if unarchiving, ok
        # Apply changes
        changed = False
        now = _now()

        if "name" in data:
            newv = data["name"].strip()
            if proj.get("name") != newv:
                proj["name"] = newv
                changed = True
        if "description" in data:
            if proj.get("description") != data["description"]:
                proj["description"] = data["description"]
                changed = True
        if "teamId" in data:
            if proj.get("team_id") != data["teamId"]:
                proj["team_id"] = data["teamId"]
                changed = True
        if "startDate" in data:
            # stored field is start_date
            if proj.get("start_date") != sd:
                proj["start_date"] = sd
                changed = True
        if "targetDate" in data:
            if proj.get("target_date") != td:
                proj["target_date"] = td
                changed = True
        if "status" in data:
            if proj.get("status") != intended_status:
                proj["status"] = intended_status
                changed = True

        if not changed:
            # idempotent: return the current project (still a successful effect? none).
            # But contract says no success without effect for mutations. If caller sent no-op, treat as conflict-free idempotent update:
            _audit(endpoint, "ok", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                   meta={"idempotent": True}, started=started)
            return {
                "project": proj,
                "meta": {"idempotent": True}
            }

        proj["updated_at"] = now
        ws_row["updated_at"] = now

        _save("linear_workspaces.json", workspaces)

        _audit(endpoint, "ok", org_id=org.get("id"), viewer_user_id=viewer_user_id, started=started,
               meta={"project_id": projectId})

        return {"project": proj}
    except Exception as e:
        _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR", "exception": type(e).__name__}, started=started)
        return _err("VALIDATION_ERROR", "Request could not be processed")

def linear_addIssueToProject(issueId, projectId, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_addIssueToProject"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status_s, org_id=None, meta=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "lin_req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "org_id": org_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("linear_request_log.json", logs)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _resolve_active_org(orgs, workspaces, issues, issue_id=None, project_id=None):
        # Find an active org that can serve this call; prefer org implied by issue/project if those exist.
        active_org_ids = [o.get("id") for o in orgs if isinstance(o, dict) and o.get("status") == "active" and isinstance(o.get("id"), str)]
        active_org_ids_set = set(active_org_ids)

        issue = None
        if issue_id is not None:
            issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id), None)

        project = None
        project_org_id = None
        if project_id is not None:
            for ws in workspaces:
                if not isinstance(ws, dict):
                    continue
                if ws.get("org_id") not in active_org_ids_set:
                    continue
                for p in (ws.get("projects") or []):
                    if isinstance(p, dict) and p.get("id") == project_id:
                        project = p
                        project_org_id = ws.get("org_id")
                        break
                if project:
                    break

        # Choose org id
        candidate_org_ids = []
        if issue and isinstance(issue.get("org_id"), str):
            candidate_org_ids.append(issue.get("org_id"))
        if project_org_id:
            candidate_org_ids.append(project_org_id)
        candidate_org_ids.extend(active_org_ids)

        chosen_org = None
        chosen_ws = None
        for oid in candidate_org_ids:
            if oid not in active_org_ids_set:
                continue
            o = next((r for r in orgs if isinstance(r, dict) and r.get("id") == oid), None)
            if not o:
                continue
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == oid), None)
            if not ws:
                continue
            chosen_org = o
            chosen_ws = ws
            break
        return chosen_org, chosen_ws, issue, project

    # Validate inputs (schema says patterns, but audit indicates callers may pass other ids; accept any non-empty string)
    if not isinstance(issueId, str) or not issueId.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "issueId"})
        return _err("VALIDATION_ERROR", "issueId must be a non-empty string", field="issueId")
    if not isinstance(projectId, str) or not projectId.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "projectId"})
        return _err("VALIDATION_ERROR", "projectId must be a non-empty string", field="projectId")

    orgs = _load("linear_org.json")
    issues = _load("linear_issues.json")
    workspaces = _load("linear_workspaces.json")
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(issues, list):
        issues = []
    if not isinstance(workspaces, list):
        workspaces = []

    org, ws, issue, project = _resolve_active_org(orgs, workspaces, issues, issue_id=issueId, project_id=projectId)
    if not org or not ws:
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    org_id = org.get("id")

    if not issue:
        _log("error", org_id=org_id, meta={"code": "NOT_FOUND", "field": "issueId"})
        return _err("NOT_FOUND", "Issue not found", issueId=issueId)
    if issue.get("org_id") != org_id:
        _log("error", org_id=org_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Issue belongs to a different organization than the active workspace", issueId=issueId, org_id=issue.get("org_id"))

    # Project must exist within the resolved workspace's projects
    if not project:
        _log("error", org_id=org_id, meta={"code": "NOT_FOUND", "field": "projectId"})
        return _err("NOT_FOUND", "Project not found", projectId=projectId)

    # Refuse edits to archived/deleted issues
    if issue.get("status") in ("archived", "deleted"):
        _log("error", org_id=org_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Issue cannot be modified in its current status", status=issue.get("status"))

    # Ensure join table exists
    if not isinstance(ws.get("project_issues"), list):
        ws["project_issues"] = []
    joins = ws["project_issues"]

    existing = next((j for j in joins if isinstance(j, dict) and j.get("project_id") == projectId and j.get("issue_id") == issueId), None)
    # Idempotent: if already attached, return current association state
    if existing:
        _log("ok", org_id=org_id, meta={"idempotent": True})
        return {
            "project_issue": existing,
            "issue": issue,
            "project": project
        }

    # Create join
    now = _now()
    join_row = {
        "id": _new_id("lin_pis_"),
        "project_id": projectId,
        "issue_id": issueId,
        "created_at": now
    }
    joins.append(join_row)
    ws["updated_at"] = now
    _save("linear_workspaces.json", workspaces)

    # Add immutable history event on issue (added_to_project)
    if not isinstance(issue.get("issue_history"), list):
        issue["issue_history"] = []
    issue["issue_history"].append({
        "id": _new_id("lin_hst_"),
        "issue_id": issueId,
        "actor_user_id": org.get("viewer_user_id"),
        "event_type": "added_to_project",
        "field_name": "project_id",
        "from_value": None,
        "to_value": {"project_id": projectId},
        "created_at": now
    })
    issue["updated_at"] = now
    _save("linear_issues.json", issues)

    _log("ok", org_id=org_id)
    return {
        "project_issue": join_row,
        "issue": issue,
        "project": project
    }

def linear_getProjectIssues(projectId, status=None, stateId=None, assigneeUserId=None, priority=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
