            logs = []
        ts = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int(max(0, (time.time() - started) * 1000))
        logs.append({
            "id": "lin_aud_" + hashlib.sha256((ts + endpoint + str(status_s) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26],
            "timestamp": ts,
            "endpoint": endpoint,
            "status": status_s,
            "org_id": org_id,
            "viewer_user_id": viewer_user_id,
            "latency_ms": latency_ms,
            "meta": meta or {}
        })
        _save("linear_audit_log.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "cursor is invalid")
            return obj
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    started = time.time()
    endpoint = "linear_getProjectIssues"

    try:
        if not isinstance(projectId, str) or not re.match(r"^lin_prj_[0-9A-HJKMNP-TV-Z]{26}$", projectId):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "projectId format is invalid")

        if status is not None and status not in ("active", "archived", "deleted"):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")
        if priority is not None and priority not in (0, 1, 2, 3, 4):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "priority must be one of: 0,1,2,3,4")
        if assigneeUserId is not None:
            if not isinstance(assigneeUserId, str) or not re.match(r"^lin_usr_[0-9A-HJKMNP-TV-Z]{26}$", assigneeUserId):
                _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "assigneeUserId format is invalid")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

        if sort is None:
            sort = "updatedAt"
        if sort not in ("updatedAt", "createdAt", "priority"):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "sort must be one of: updatedAt, createdAt, priority")

        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

        cur_obj = _decode_cursor(cursor)
        if isinstance(cur_obj, dict) and cur_obj.get("error"):
            _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
            return cur_obj
        offset = 0
        if cur_obj is not None:
            if cur_obj.get("projectId") != projectId:
                _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "cursor does not match projectId")
            off = cur_obj.get("offset")
            if not isinstance(off, int) or off < 0:
                _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = off

        orgs = _load("linear_org.json")
        if not isinstance(orgs, list):
            orgs = []
        active_orgs = [o for o in orgs if isinstance(o, dict) and o.get("status") == "active"]
        if not active_orgs:
            _audit(endpoint, "error", meta={"code": "UNAUTHORIZED"}, started=started)
            return _err("UNAUTHORIZED", "No active Linear organization connection")

        workspaces = _load("linear_workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        issues = _load("linear_issues.json")
        if not isinstance(issues, list):
