        # Resolve project within an active org
        ws_row = None
        project = None
        org = None
        for o in active_orgs:
            oid = o.get("id")
            if not isinstance(oid, str):
                continue
            for w in workspaces:
                if not isinstance(w, dict) or w.get("org_id") != oid:
                    continue
                projects = w.get("projects")
                if not isinstance(projects, list):
                    continue
                for p in projects:
                    if isinstance(p, dict) and p.get("id") == projectId:
                        ws_row = w
                        project = p
                        org = o
                        break
                if project is not None:
                    break
            if project is not None:
                break

        if project is None or ws_row is None or org is None:
            _audit(endpoint, "error", meta={"code": "NOT_FOUND"}, started=started)
            return _err("NOT_FOUND", "Project does not exist")

        viewer_user_id = org.get("viewer_user_id")

        joins = ws_row.get("project_issues")
        if not isinstance(joins, list):
            joins = []

        issue_ids = [j.get("issue_id") for j in joins if isinstance(j, dict) and j.get("project_id") == projectId and isinstance(j.get("issue_id"), str)]
        idset = set(issue_ids)

        rows = [it for it in issues if isinstance(it, dict) and it.get("org_id") == ws_row.get("org_id") and it.get("id") in idset]

        # filters
        if status is not None:
            rows = [r for r in rows if r.get("status") == status]
        if stateId is not None:
            if not isinstance(stateId, str) or not stateId:
                _audit(endpoint, "error", org_id=org.get("id"), viewer_user_id=viewer_user_id,
                       meta={"code": "VALIDATION_ERROR"}, started=started)
                return _err("VALIDATION_ERROR", "stateId must be a non-empty string")
            rows = [r for r in rows if r.get("state_id") == stateId]
        if assigneeUserId is not None:
            rows = [r for r in rows if r.get("assignee_user_id") == assigneeUserId]
        if priority is not None:
            rows = [r for r in rows if r.get("priority") == priority]

        # sort
        reverse = (order == "desc")
        if sort == "updatedAt":
            keyfn = lambda r: (r.get("updated_at") or "", r.get("id") or "")
        elif sort == "createdAt":
            keyfn = lambda r: (r.get("created_at") or "", r.get("id") or "")
        else:  # priority
            keyfn = lambda r: (r.get("priority") if isinstance(r.get("priority"), int) else 999, r.get("updated_at") or "", r.get("id") or "")

        rows_sorted = sorted(rows, key=keyfn, reverse=reverse)

        total = len(rows_sorted)
        page = rows_sorted[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = _encode_cursor({"projectId": projectId, "offset": next_offset}) if has_more else None

        _audit(endpoint, "ok", org_id=org.get("id"), viewer_user_id=viewer_user_id,
               meta={"total": total, "returned": len(page)}, started=started)

        return {
            "issues": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more
            }
        }
    except Exception as e:
        _audit(endpoint, "error", meta={"code": "VALIDATION_ERROR", "exception": type(e).__name__}, started=started)
        return _err("VALIDATION_ERROR", "Request could not be processed")

def linear_getCycles(teamId=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_getCycles"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status_s, org_id=None, meta=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "lin_req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "org_id": org_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("linear_request_log.json", logs)

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        # allow opaque cursors; if not decodable, treat as 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("offset:"):
                off = int(s.split(":", 1)[1])
                return off if off >= 0 else None
            return 0
        except Exception:
            return 0

    def _make_cursor(off):
        return base64.urlsafe_b64encode(f"offset:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Validate enums/ranges; teamId: accept any non-empty string (audit shows callers pass other ids)
    if teamId is not None and (not isinstance(teamId, str) or not teamId.strip()):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "teamId"})
        return _err("VALIDATION_ERROR", "teamId must be a non-empty string when provided", field="teamId")
    if status is not None and status not in ("active", "archived", "deleted"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "status"})
        return _err("VALIDATION_ERROR", "status is invalid", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")
    if sort is None:
        sort = "updatedAt"
    if sort not in ("updatedAt", "createdAt", "startDate", "endDate"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "sort"})
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "order"})
        return _err("VALIDATION_ERROR", "order is invalid", field="order")

    off = _parse_cursor(cursor)
    if off is None:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    orgs = _load("linear_org.json")
    workspaces = _load("linear_workspaces.json")
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(workspaces, list):
        workspaces = []

    # Resolve a single active org that has a workspace and, if teamId provided, contains that team.
    active_orgs = [o for o in orgs if isinstance(o, dict) and o.get("status") == "active"]
    chosen_org = None
    chosen_ws = None
    team_found = False

    for o in active_orgs:
        oid = o.get("id")
        if not isinstance(oid, str):
            continue
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == oid), None)
        if not ws:
            continue
        if teamId is None:
            chosen_org, chosen_ws = o, ws
            team_found = True
            break
        teams = ws.get("teams") or []
        if any(isinstance(t, dict) and t.get("id") == teamId for t in teams):
            chosen_org, chosen_ws = o, ws
            team_found = True
            break

    if not chosen_org or not chosen_ws:
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    org_id = chosen_org.get("id")

    # If teamId provided but not found in active workspace: NOT_FOUND
    if teamId is not None and not team_found:
        _log("error", org_id=org_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Team not found", teamId=teamId)

    cycles = chosen_ws.get("cycles") or []
    rows = [c for c in cycles if isinstance(c, dict)]
    if teamId is not None:
        rows = [c for c in rows if c.get("team_id") == teamId]

    # Map API status filter to stored cycle statuses (planned/active/completed/canceled)
    # If status filter is used, interpret:
    # - active => only active
    # - archived => completed or canceled
    # - deleted => none (no deleted cycles in schema)
    if status is not None:
        if status == "active":
            rows = [c for c in rows if c.get("status") == "active"]
        elif status == "archived":
            rows = [c for c in rows if c.get("status") in ("completed", "canceled")]
        elif status == "deleted":
            rows = []

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _sort_key(c):
        if sort == "updatedAt":
            return _dt(c.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if sort == "createdAt":
            return _dt(c.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if sort == "startDate":
            return _dt(c.get("starts_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if sort == "endDate":
            return _dt(c.get("ends_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows_sorted = sorted(rows, key=_sort_key, reverse=(order == "desc"))
    total = len(rows_sorted)
    page = rows_sorted[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log("ok", org_id=org_id, meta={"total": total})
    return {
        "cycles": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def linear_getActiveCycle(teamId, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_getActiveCycle"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status_s, org_id=None, meta=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "lin_req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "org_id": org_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("linear_request_log.json", logs)

    if not isinstance(teamId, str) or not teamId.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "teamId"})
        return _err("VALIDATION_ERROR", "teamId must be a non-empty string", field="teamId")

    orgs = _load("linear_org.json")
    workspaces = _load("linear_workspaces.json")
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(workspaces, list):
        workspaces = []

    active_orgs = [o for o in orgs if isinstance(o, dict) and o.get("status") == "active" and isinstance(o.get("id"), str)]
    chosen_org = None
    chosen_ws = None
    for o in active_orgs:
        oid = o.get("id")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == oid), None)
        if not ws:
            continue
        teams = ws.get("teams") or []
        if any(isinstance(t, dict) and t.get("id") == teamId for t in teams):
            chosen_org, chosen_ws = o, ws
            break

    if not chosen_org or not chosen_ws:
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    org_id = chosen_org.get("id")

    cycles = [c for c in (chosen_ws.get("cycles") or []) if isinstance(c, dict) and c.get("team_id") == teamId]
    active = [c for c in cycles if c.get("status") == "active"]

    if not any(isinstance(t, dict) and t.get("id") == teamId for t in (chosen_ws.get("teams") or [])):
        _log("error", org_id=org_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Team not found", teamId=teamId)

    if not active:
        _log("error", org_id=org_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No active cycle found for team", teamId=teamId)

    # Enforce at most one active per team: if multiple, pick the most recently updated but record inconsistency in meta.
    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None
    active_sorted = sorted(active, key=lambda c: _dt(c.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)
    chosen = active_sorted[0]
    _log("ok", org_id=org_id, meta={"multiple_active": len(active_sorted) > 1})
    return {"cycle": chosen}

def linear_addIssueToCycle(issueId, cycleId, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_addIssueToCycle"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status_s, org_id=None, meta=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "lin_req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "org_id": org_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("linear_request_log.json", logs)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    # Accept any non-empty strings (audit shows callers may pass ids that don't match tool regex)
    if not isinstance(issueId, str) or not issueId.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "issueId"})
        return _err("VALIDATION_ERROR", "issueId must be a non-empty string", field="issueId")
    if not isinstance(cycleId, str) or not cycleId.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "cycleId"})
        return _err("VALIDATION_ERROR", "cycleId must be a non-empty string", field="cycleId")

    orgs = _load("linear_org.json")
    issues = _load("linear_issues.json")
    workspaces = _load("linear_workspaces.json")
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(issues, list):
        issues = []
    if not isinstance(workspaces, list):
        workspaces = []

    issue = next((r for r in issues if isinstance(r, dict) and r.get("id") == issueId), None)
    if not issue:
        # Still resolve an active org for logging if possible
        active_org = next((o for o in orgs if isinstance(o, dict) and o.get("status") == "active"), None)
        _log("error", org_id=(active_org or {}).get("id"), meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Issue not found", issueId=issueId)

    org_id = issue.get("org_id")
    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id and o.get("status") == "active"), None)
    if not org:
        _log("error", org_id=org_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == org_id), None)
    if not ws:
        _log("error", org_id=org_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Linear organization workspace is missing for active org")

    # Find cycle in this org
    cycle = next((c for c in (ws.get("cycles") or []) if isinstance(c, dict) and c.get("id") == cycleId), None)
    if not cycle:
        _log("error", org_id=org_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Cycle not found", cycleId=cycleId)

    if issue.get("status") in ("archived", "deleted"):
        _log("error", org_id=org_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Issue cannot be modified in its current status", status=issue.get("status"))

    # Team compatibility rule
    if cycle.get("team_id") != issue.get("team_id"):
        _log("error", org_id=org_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Issue cannot be added to a cycle from a different team", issueTeamId=issue.get("team_id"), cycleTeamId=cycle.get("team_id"))

    if not isinstance(ws.get("cycle_issues"), list):
        ws["cycle_issues"] = []
    joins = ws["cycle_issues"]
    existing = next((j for j in joins if isinstance(j, dict) and j.get("cycle_id") == cycleId and j.get("issue_id") == issueId), None)
    if existing:
        _log("ok", org_id=org_id, meta={"idempotent": True})
        return {"cycle_issue": existing, "issue": issue, "cycle": cycle}

    now = _now()
    join_row = {
        "id": _new_id("lin_cis_"),
        "cycle_id": cycleId,
        "issue_id": issueId,
        "created_at": now
    }
    joins.append(join_row)
    ws["updated_at"] = now
    _save("linear_workspaces.json", workspaces)

    # history event on issue
    if not isinstance(issue.get("issue_history"), list):
        issue["issue_history"] = []
    issue["issue_history"].append({
        "id": _new_id("lin_hst_"),
        "issue_id": issueId,
        "actor_user_id": org.get("viewer_user_id"),
        "event_type": "added_to_cycle",
        "field_name": "cycle_id",
        "from_value": None,
        "to_value": {"cycle_id": cycleId},
        "created_at": now
    })
    issue["updated_at"] = now
    _save("linear_issues.json", issues)

    _log("ok", org_id=org_id)
    return {"cycle_issue": join_row, "issue": issue, "cycle": cycle}

def linear_getIssues(orgId=None, teamId=None, assigneeUserId=None, creatorUserId=None, stateId=None, status=None, priority=None, updatedAfter=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
