        if not isinstance(s, str) or not s:
            return None
        try:
            # handle Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _get_active_org():
        orgs = _load("linear_org.json")
        for o in orgs:
            if isinstance(o, dict) and o.get("status") == "active":
                return o
        return None

    def _log(endpoint, status_s, org_id=None, meta=None, started=None):
        try:
            logs = _load("request_log.json")
