    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur + "=" * (-len(cur) % 4)).decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(offset):
        raw = f"offset:{offset}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    started = time.time()

    # Validate enums/ranges
    if orgId is not None:
        if not isinstance(orgId, str) or not re.match(r"^lin_org_[0-9A-HJKMNP-TV-Z]{26}$", orgId):
            _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "orgId"}, started)
            return _err("VALIDATION_ERROR", "orgId has invalid format.", field="orgId")

    if teamId is not None:
        if not isinstance(teamId, str) or not re.match(r"^lin_team_[0-9A-HJKMNP-TV-Z]{26}$", teamId):
