            return _err("VALIDATION_ERROR", "assigneeUserId has invalid format.", field="assigneeUserId")

    if creatorUserId is not None:
        if not isinstance(creatorUserId, str) or not re.match(r"^lin_usr_[0-9A-HJKMNP-TV-Z]{26}$", creatorUserId):
            _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "creatorUserId"}, started)
            return _err("VALIDATION_ERROR", "creatorUserId has invalid format.", field="creatorUserId")

    if stateId is not None:
        if not isinstance(stateId, str) or not stateId:
            _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "stateId"}, started)
            return _err("VALIDATION_ERROR", "stateId must be a non-empty string.", field="stateId")

    if status is not None:
        if status not in ("active", "archived", "deleted"):
            _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "status"}, started)
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.", field="status")

    if priority is not None:
        if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
            _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "priority"}, started)
            return _err("VALIDATION_ERROR", "priority must be an integer in [0,4].", field="priority")

    ua = None
    if updatedAfter is not None:
        if not isinstance(updatedAfter, str):
            _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "updatedAfter"}, started)
            return _err("VALIDATION_ERROR", "updatedAfter must be an RFC3339 date-time string.", field="updatedAfter")
        ua = _parse_dt(updatedAfter)
        if ua is None:
            _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "updatedAfter"}, started)
            return _err("VALIDATION_ERROR", "updatedAfter has invalid date-time format.", field="updatedAfter")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "limit"}, started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    if sort is None:
        sort = "updatedAt"
    if sort not in ("updatedAt", "createdAt", "priority"):
        _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "sort"}, started)
        return _err("VALIDATION_ERROR", "sort must be one of: updatedAt, createdAt, priority.", field="sort")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "order"}, started)
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", field="order")

    offset = _decode_cursor(cursor)
    if offset is None:
        _log("linear_getIssues", "VALIDATION_ERROR", None, {"field": "cursor"}, started)
        return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    org = _get_active_org()
    if not org:
        _log("linear_getIssues", "UNAUTHORIZED", None, {}, started)
        return _err("UNAUTHORIZED", "No active Linear organization connection is available.")

    if orgId is not None and orgId != org.get("id"):
        _log("linear_getIssues", "UNAUTHORIZED", org.get("id"), {"orgId": orgId}, started)
        return _err("UNAUTHORIZED", "You do not have access to the requested organization.", orgId=orgId)

    issues = _load("linear_issues.json")
    if not isinstance(issues, list):
        issues = []

    # base scope: active org only
    scoped = [it for it in issues if isinstance(it, dict) and it.get("org_id") == org.get("id")]

    # filters
    if teamId is not None:
        scoped = [it for it in scoped if it.get("team_id") == teamId]
    if assigneeUserId is not None:
        scoped = [it for it in scoped if it.get("assignee_user_id") == assigneeUserId]
    if creatorUserId is not None:
        scoped = [it for it in scoped if it.get("creator_user_id") == creatorUserId]
    if stateId is not None:
        scoped = [it for it in scoped if it.get("state_id") == stateId]
    if status is not None:
        scoped = [it for it in scoped if it.get("status") == status]
    if priority is not None:
        scoped = [it for it in scoped if it.get("priority") == priority]
    if ua is not None:
        def _after(it):
            d = _parse_dt(it.get("updated_at"))
            return d is not None and d > ua
        scoped = [it for it in scoped if _after(it)]

    # sort
    def _sort_key(it):
        if sort == "updatedAt":
            d = _parse_dt(it.get("updated_at"))
            return d or datetime.datetime.min
        if sort == "createdAt":
            d = _parse_dt(it.get("created_at"))
            return d or datetime.datetime.min
        # priority
        p = it.get("priority")
        return p if isinstance(p, int) else -1

    reverse = (order == "desc")
    scoped.sort(key=_sort_key, reverse=reverse)

    total = len(scoped)
    page = scoped[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log("linear_getIssues", "OK", org.get("id"), {"total": total, "returned": len(page), "has_more": has_more}, started)
    return {
        "issues": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def linear_getIssueById(id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_active_org():
        orgs = _load("linear_org.json")
        for o in orgs:
            if isinstance(o, dict) and o.get("status") == "active":
                return o
        return None

    def _log(endpoint, status, org_id=None, meta=None, started=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = None
            if started is not None:
                latency_ms = int((time.time() - started) * 1000)
            logs.append({
                "id": "req_" + base64.b32encode(os.urandom(16)).decode("utf-8").rstrip("=").lower(),
                "endpoint": endpoint,
                "org_id": org_id,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now(),
                "meta": meta or {}
            })
            _save("request_log.json", logs)
        except Exception:
            pass

    started = time.time()

    if not isinstance(id, str) or not id.strip():
        _log("linear_getIssueById", "VALIDATION_ERROR", None, {"field": "id"}, started)
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    value = id.strip()

    is_local = bool(re.match(r"^lin_iss_[0-9A-HJKMNP-TV-Z]{26}$", value))
    is_ident = bool(re.match(r"^[A-Z][A-Z0-9]*-[0-9]+$", value))
    if not is_local and not is_ident:
        _log("linear_getIssueById", "VALIDATION_ERROR", None, {"field": "id"}, started)
        return _err("VALIDATION_ERROR", "id must be a local issue id (lin_iss_...) or an identifier like ABC-123.", field="id")

    org = _get_active_org()
    if not org:
        _log("linear_getIssueById", "UNAUTHORIZED", None, {}, started)
        return _err("UNAUTHORIZED", "No active Linear organization connection is available.")

    issues = _load("linear_issues.json")
    if not isinstance(issues, list):
        issues = []

    matches = []
    if is_local:
        matches = [it for it in issues if isinstance(it, dict) and it.get("id") == value and it.get("org_id") == org.get("id")]
    else:
        # identifier must be unique per org
        matches = [it for it in issues if isinstance(it, dict) and it.get("identifier") == value and it.get("org_id") == org.get("id")]

    if not matches:
        _log("linear_getIssueById", "NOT_FOUND", org.get("id"), {"id": value}, started)
        return _err("NOT_FOUND", "Issue not found.", id=value)

    # If multiple (shouldn't happen), treat as conflict-like data inconsistency but return first deterministically
    issue = sorted(matches, key=lambda x: x.get("updated_at") or "", reverse=True)[0]
    _log("linear_getIssueById", "OK", org.get("id"), {"id": value, "issueId": issue.get("id")}, started)
    return {"issue": issue}

def linear_searchIssues(org_id=None, team_id=None, assignee_user_id=None, creator_user_id=None, state_id=None, priority=None, status=None, parent_issue_id=None, identifier=None, query=None, created_after=None, created_before=None, updated_after=None, updated_before=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_searchIssues"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time")

    def _is_str(x):
        return x is None or isinstance(x, str)

    def _audit(status_code, credential_id, org_row_id, extra=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{hashlib.sha256((endpoint + _now_iso() + str(time.time())).encode('utf-8')).hexdigest()[:24]}",
            "endpoint": endpoint,
            "status": status_code,
            "credential_id": credential_id,
            "org_id": org_row_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("linear_request_log.json", logs)

    # Basic type validation
    for nm, val in [
        ("org_id", org_id), ("team_id", team_id), ("assignee_user_id", assignee_user_id),
        ("creator_user_id", creator_user_id), ("state_id", state_id), ("parent_issue_id", parent_issue_id),
        ("identifier", identifier), ("query", query), ("cursor", cursor), ("sort_by", sort_by), ("sort_order", sort_order),
        ("status", status)
    ]:
        if not _is_str(val):
            _audit("VALIDATION_ERROR", None, None)
            return _err("VALIDATION_ERROR", f"{nm} must be a string")

    if priority is not None and not isinstance(priority, int):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "priority must be an integer")
    if priority is not None and priority not in (0, 1, 2, 3, 4):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "priority must be one of 0,1,2,3,4")

    if status is not None and status not in ("active", "archived", "deleted"):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "status must be one of active, archived, deleted")

    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at", "priority", "due_date"):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "sort_by must be one of created_at, updated_at, priority, due_date")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "sort_order must be one of asc, desc")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        _audit("VALIDATION_ERROR", None, None)
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        _audit("VALIDATION_ERROR", None, None)
        return cb
    ua = _parse_dt(updated_after, "updated_after")
    if isinstance(ua, dict) and "error" in ua:
        _audit("VALIDATION_ERROR", None, None)
        return ua
    ub = _parse_dt(updated_before, "updated_before")
    if isinstance(ub, dict) and "error" in ub:
        _audit("VALIDATION_ERROR", None, None)
        return ub

    # Resolve active org context (ambient auth): pick an active org that satisfies request
    orgs = _load("linear_org.json")
    if not isinstance(orgs, list):
        orgs = []
    active_orgs = [o for o in orgs if isinstance(o, dict) and o.get("status") == "active"]
    if org_id is not None:
        active_orgs = [o for o in active_orgs if o.get("id") == org_id]
    if not active_orgs:
        _audit("UNAUTHORIZED", None, org_id)
        return _err("UNAUTHORIZED", "No active Linear organization connection available for this request")

    org_row = active_orgs[0]
    org_row_id = org_row.get("id")

    # Load dependencies
    users = _load("linear_users.json")
    if not isinstance(users, list):
        users = []
    issues = _load("linear_issues.json")
    if not isinstance(issues, list):
        issues = []
    workspaces = _load("linear_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == org_row_id), None)
    if ws is None:
        _audit("NOT_FOUND", None, org_row_id)
        return _err("NOT_FOUND", "Workspace data not found for organization", org_id=org_row_id)

    teams = ws.get("teams") or []
    workflow_states = ws.get("workflow_states") or []

    def _team_exists(tid):
        return any(isinstance(t, dict) and t.get("id") == tid for t in teams)

    def _state_exists(sid):
        return any(isinstance(s, dict) and s.get("id") == sid for s in workflow_states)

    def _user_exists(uid):
        return any(isinstance(u, dict) and u.get("id") == uid and u.get("org_id") == org_row_id for u in users)

    # Validate referenced filter ids exist when provided (NOT_FOUND)
    if team_id is not None and not _team_exists(team_id):
        _audit("NOT_FOUND", None, org_row_id)
        return _err("NOT_FOUND", "team_id not found", team_id=team_id)
    if state_id is not None and not _state_exists(state_id):
        _audit("NOT_FOUND", None, org_row_id)
        return _err("NOT_FOUND", "state_id not found", state_id=state_id)
    if assignee_user_id is not None and not _user_exists(assignee_user_id):
        _audit("NOT_FOUND", None, org_row_id)
        return _err("NOT_FOUND", "assignee_user_id not found", assignee_user_id=assignee_user_id)
    if creator_user_id is not None and not _user_exists(creator_user_id):
        _audit("NOT_FOUND", None, org_row_id)
        return _err("NOT_FOUND", "creator_user_id not found", creator_user_id=creator_user_id)

    # Filter base set
    results = []
    q = (query or "").strip().lower()
    for it in issues:
        if not isinstance(it, dict):
            continue
        if it.get("org_id") != org_row_id:
            continue
        # Field filters
        if team_id is not None and it.get("team_id") != team_id:
            continue
        if assignee_user_id is not None and it.get("assignee_user_id") != assignee_user_id:
            continue
        if creator_user_id is not None and it.get("creator_user_id") != creator_user_id:
            continue
        if state_id is not None and it.get("state_id") != state_id:
            continue
        if priority is not None and it.get("priority") != priority:
            continue
        if status is not None and it.get("status") != status:
            continue
        if parent_issue_id is not None and it.get("parent_issue_id") != parent_issue_id:
            continue
        if identifier is not None and it.get("identifier") != identifier:
            continue

        # Date filters (compare as datetimes where possible)
        def _dt_field(val):
            if not isinstance(val, str):
                return None
            try:
                vv = val.strip()
                if vv.endswith("Z"):
                    vv = vv[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(vv)
            except Exception:
                return None

        cdt = _dt_field(it.get("created_at"))
        udt = _dt_field(it.get("updated_at"))
        if ca is not None and cdt is not None and cdt <= ca:
            continue
        if cb is not None and cdt is not None and cdt >= cb:
            continue
        if ua is not None and udt is not None and udt <= ua:
            continue
        if ub is not None and udt is not None and udt >= ub:
            continue

        # Full text
        if q:
            tt = (it.get("title") or "")
            dd = (it.get("description") or "")
            if (not isinstance(tt, str)) or (not isinstance(dd, str)):
                # coerce non-string to fail match
                pass
            hay = (tt + "\n" + dd).lower()
            if q not in hay:
                continue

        results.append(it)

    # Sorting
    def _sort_key(x):
        if sort_by in ("created_at", "updated_at", "due_date"):
            v = x.get(sort_by)
            if not isinstance(v, str):
                # place missing at end for asc, at start for desc
                return (1, "")
            return (0, v)
        if sort_by == "priority":
            v = x.get("priority")
            if not isinstance(v, int):
                return (1, 0)
            return (0, v)
        return (0, "")

    reverse = (sort_order == "desc")
    results_sorted = sorted(results, key=_sort_key, reverse=reverse)

    # Cursor pagination: cursor encodes offset and a checksum
    offset = 0
    if cursor:
        if not isinstance(cursor, str):
            _audit("VALIDATION_ERROR", None, org_row_id)
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            parts = raw.split(":")
            if len(parts) != 3 or parts[0] != "v1":
                raise ValueError("bad cursor")
            off = int(parts[1])
            sig = parts[2]
            expected = hashlib.sha256((f"{org_row_id}:{off}:{sort_by}:{sort_order}").encode("utf-8")).hexdigest()[:16]
            if sig != expected or off < 0:
                raise ValueError("bad cursor sig")
            offset = off
        except Exception:
            _audit("VALIDATION_ERROR", None, org_row_id)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = results_sorted[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(results_sorted)
    next_cursor = None
    if has_more:
        sig = hashlib.sha256((f"{org_row_id}:{next_offset}:{sort_by}:{sort_order}").encode("utf-8")).hexdigest()[:16]
        next_cursor = base64.urlsafe_b64encode(f"v1:{next_offset}:{sig}".encode("utf-8")).decode("utf-8")

    resp = {
        "issues": page,
        "meta": {
            "total": len(results_sorted),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _audit("OK", None, org_row_id, {"result_count": len(page)})
    return resp

