        if not isinstance(estimate, (int, float)):
            _audit("VALIDATION_ERROR", None, org_id)
            return _err("VALIDATION_ERROR", "estimate must be a number")
        if estimate < 0:
            _audit("VALIDATION_ERROR", None, org_id)
            return _err("VALIDATION_ERROR", "estimate must be >= 0")
    dd = _parse_dt(due_date, "due_date")
    if isinstance(dd, dict) and "error" in dd:
        _audit("VALIDATION_ERROR", None, org_id)
        return dd

    # Resolve active org context
    orgs = _load("linear_org.json")
    if not isinstance(orgs, list):
        orgs = []
    org_row = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id), None)
    if org_row is None:
        _audit("NOT_FOUND", None, org_id)
        return _err("NOT_FOUND", "Organization not found", org_id=org_id)
    if org_row.get("status") != "active":
        _audit("UNAUTHORIZED", None, org_id)
        return _err("UNAUTHORIZED", "Linear organization connection is not active", org_id=org_id, status=org_row.get("status"))

    # Load workspace
    workspaces = _load("linear_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == org_id), None)
    if ws is None:
        _audit("NOT_FOUND", None, org_id)
        return _err("NOT_FOUND", "Workspace data not found for organization", org_id=org_id)

    teams = ws.get("teams") or []
    workflow_states = ws.get("workflow_states") or []

    team_row = next((t for t in teams if isinstance(t, dict) and t.get("id") == team_id), None)
    if team_row is None:
        _audit("NOT_FOUND", None, org_id)
        return _err("NOT_FOUND", "Team not found", team_id=team_id)

    # Determine default state if not provided: pick first active state for team by position
    if state_id is None:
        team_states = [s for s in workflow_states if isinstance(s, dict) and s.get("team_id") == team_id and s.get("status") == "active"]
        if not team_states:
            _audit("NOT_FOUND", None, org_id)
            return _err("NOT_FOUND", "No workflow states found for team", team_id=team_id)
        team_states_sorted = sorted(team_states, key=lambda s: (s.get("position") if isinstance(s.get("position"), int) else 10**9))
        state_row = team_states_sorted[0]
        state_id = state_row.get("id")
    else:
        state_row = next((s for s in workflow_states if isinstance(s, dict) and s.get("id") == state_id), None)
        if state_row is None:
            _audit("NOT_FOUND", None, org_id)
            return _err("NOT_FOUND", "Workflow state not found", state_id=state_id)
        if state_row.get("team_id") != team_id:
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "state_id must belong to the same team as team_id", team_id=team_id, state_id=state_id)

    # Validate assignee
    users = _load("linear_users.json")
    if not isinstance(users, list):
        users = []
    if assignee_user_id is not None:
        u = next((x for x in users if isinstance(x, dict) and x.get("id") == assignee_user_id and x.get("org_id") == org_id), None)
        if u is None:
            _audit("NOT_FOUND", None, org_id)
            return _err("NOT_FOUND", "Assignee user not found", assignee_user_id=assignee_user_id)
        if u.get("status") != "active" or not u.get("is_active", True):
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "Cannot assign issue to disabled/deleted user", assignee_user_id=assignee_user_id, user_status=u.get("status"))

    # Validate parent issue
    issues = _load("linear_issues.json")
    if not isinstance(issues, list):
        issues = []
    if parent_issue_id is not None:
        parent = next((x for x in issues if isinstance(x, dict) and x.get("id") == parent_issue_id), None)
        if parent is None:
            _audit("NOT_FOUND", None, org_id)
            return _err("NOT_FOUND", "parent_issue_id not found", parent_issue_id=parent_issue_id)
        if parent.get("org_id") != org_id:
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "Parent issue must be in the same organization", parent_issue_id=parent_issue_id)
        if parent.get("team_id") != team_id:
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "Parent and child must be in the same team", parent_issue_id=parent_issue_id, team_id=team_id)

    # Generate new IDs and identifier
    team_key = team_row.get("key")
    if not isinstance(team_key, str) or not re.match(r"^[A-Z][A-Z0-9]*$", team_key):
        _audit("VALIDATION_ERROR", None, org_id)
        return _err("VALIDATION_ERROR", "Team key is invalid; cannot generate issue identifier", team_id=team_id)

    max_seq = 0
    pat = re.compile(rf"^{re.escape(team_key)}-(\d+)$")
    for it in issues:
        if isinstance(it, dict) and it.get("org_id") == org_id and isinstance(it.get("identifier"), str):
            m = pat.match(it["identifier"])
            if m:
                try:
                    max_seq = max(max_seq, int(m.group(1)))
                except Exception:
                    pass
    new_seq = max_seq + 1
    new_identifier = f"{team_key}-{new_seq}"

    # Ensure identifier uniqueness per org (constraint)
    if any(isinstance(it, dict) and it.get("org_id") == org_id and it.get("identifier") == new_identifier for it in issues):
        # Extremely unlikely; resolve by incrementing until free
        while any(isinstance(it, dict) and it.get("org_id") == org_id and it.get("identifier") == f"{team_key}-{new_seq}" for it in issues):
            new_seq += 1
        new_identifier = f"{team_key}-{new_seq}"

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256((prefix + _now_iso() + str(random.random())).encode('utf-8')).hexdigest()[:20]}"

    issue_id = _new_id("lin_iss_")
    linear_issue_id = _new_id("lin_up_")  # upstream id placeholder for local store uniqueness

    # Uniqueness constraints: (org_id, linear_issue_id) and (org_id, identifier)
    if any(isinstance(it, dict) and it.get("org_id") == org_id and it.get("linear_issue_id") == linear_issue_id for it in issues):
        linear_issue_id = _new_id("lin_up_")
    if any(isinstance(it, dict) and it.get("org_id") == org_id and it.get("identifier") == new_identifier for it in issues):
        _audit("CONFLICT", None, org_id)
        return _err("CONFLICT", "Issue identifier already exists", identifier=new_identifier)

    viewer_user_id = org_row.get("viewer_user_id")
    creator_user_id = viewer_user_id if isinstance(viewer_user_id, str) else None

    now = _now_iso()
    new_issue = {
        "id": issue_id,
        "org_id": org_id,
        "linear_issue_id": linear_issue_id,
        "identifier": new_identifier,
        "team_id": team_id,
        "title": title.strip(),
        "description": description if description is not None else None,
        "state_id": state_id,
        "priority": priority,
        "estimate": float(estimate) if isinstance(estimate, (int, float)) else None,
        "assignee_user_id": assignee_user_id,
        "creator_user_id": creator_user_id,
        "parent_issue_id": parent_issue_id,
        "due_date": due_date if due_date is not None else None,
        "status": "active",
        "archived_at": None,
        "created_at": now,
        "updated_at": now,
        "issue_labels": [],
        "issue_subscriptions": [],
        "issue_relations": [],
        "issue_history": []
    }

    # History event: created
    hist_id = _new_id("lin_hst_")
    new_issue["issue_history"].append({
        "id": hist_id,
        "issue_id": issue_id,
        "actor_user_id": creator_user_id,
        "event_type": "created",
        "field_name": None,
        "from_value": None,
        "to_value": {
            "title": new_issue["title"],
            "team_id": team_id,
            "state_id": state_id,
            "priority": priority
        },
        "created_at": now
    })

    issues.append(new_issue)
    _save("linear_issues.json", issues)
    _audit("OK", None, org_id, {"issue_id": issue_id})
    return {"issue": new_issue}

def linear_updateIssue(issue_id, title=None, description=None, state_id=None, priority=None, estimate=None, assignee_user_id=None, parent_issue_id=None, due_date=None, status=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_updateIssue"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status_code, credential_id, org_row_id, extra=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lin_req_{hashlib.sha256((endpoint + _now_iso() + str(time.time())).encode('utf-8')).hexdigest()[:24]}",
            "endpoint": endpoint,
            "status": status_code,
            "credential_id": credential_id,
            "org_id": org_row_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("linear_request_log.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            datetime.datetime.fromisoformat(ss)
            return s
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time")

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256((prefix + _now_iso() + str(random.random())).encode('utf-8')).hexdigest()[:20]}"

    # Validate inputs
    if not isinstance(issue_id, str) or not issue_id:
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "issue_id is required and must be a string")
    if title is not None and (not isinstance(title, str) or not title.strip()):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "title must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "description must be a string")
    if state_id is not None and not isinstance(state_id, str):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "state_id must be a string")
    if assignee_user_id is not None and not isinstance(assignee_user_id, str):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "assignee_user_id must be a string (use null to unassign)")
    if parent_issue_id is not None and not isinstance(parent_issue_id, str):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "parent_issue_id must be a string")
    if priority is not None and (not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4)):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "priority must be an integer in [0,4]")
    if estimate is not None:
        if not isinstance(estimate, (int, float)):
            _audit("VALIDATION_ERROR", None, None)
            return _err("VALIDATION_ERROR", "estimate must be a number")
        if estimate < 0:
            _audit("VALIDATION_ERROR", None, None)
            return _err("VALIDATION_ERROR", "estimate must be >= 0")
    dd = _parse_dt(due_date, "due_date")
    if isinstance(dd, dict) and "error" in dd:
        _audit("VALIDATION_ERROR", None, None)
        return dd
    if status is not None and status not in ("active", "archived", "deleted"):
        _audit("VALIDATION_ERROR", None, None)
        return _err("VALIDATION_ERROR", "status must be one of active, archived, deleted")

    issues = _load("linear_issues.json")
    if not isinstance(issues, list):
        issues = []
    idx = next((i for i, it in enumerate(issues) if isinstance(it, dict) and it.get("id") == issue_id), None)
    if idx is None:
        _audit("NOT_FOUND", None, None)
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    issue = issues[idx]
    org_id = issue.get("org_id")

    # Active org required for reads/updates; also used as "connection" check
    orgs = _load("linear_org.json")
    if not isinstance(orgs, list):
        orgs = []
    org_row = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id), None)
    if org_row is None:
        _audit("NOT_FOUND", None, org_id)
        return _err("NOT_FOUND", "Organization not found for issue", org_id=org_id)
    if org_row.get("status") != "active":
        _audit("UNAUTHORIZED", None, org_id)
        return _err("UNAUTHORIZED", "Linear organization connection is not active", org_id=org_id, status=org_row.get("status"))

    # Archived issue modification rule: archived issues can only be unarchived (status back to active)
    if issue.get("status") == "archived":
        allowed = (status == "active") and all(v is None for v in [title, description, state_id, priority, estimate, assignee_user_id, parent_issue_id, due_date])
        if not allowed:
            _audit("INVALID_TRANSITION", None, org_id)
            return _err("INVALID_TRANSITION", "Archived issues cannot be modified except unarchive")

    # Validate referenced ids
    users = _load("linear_users.json")
    if not isinstance(users, list):
        users = []
    workspaces = _load("linear_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == org_id), None)
    if ws is None:
        _audit("NOT_FOUND", None, org_id)
        return _err("NOT_FOUND", "Workspace data not found for organization", org_id=org_id)
    workflow_states = ws.get("workflow_states") or []

    if state_id is not None:
        st = next((s for s in workflow_states if isinstance(s, dict) and s.get("id") == state_id), None)
        if st is None:
            _audit("NOT_FOUND", None, org_id)
            return _err("NOT_FOUND", "Workflow state not found", state_id=state_id)
        if st.get("team_id") != issue.get("team_id"):
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "state_id must belong to the same team as the issue", team_id=issue.get("team_id"), state_id=state_id)

    if assignee_user_id is not None:
        u = next((x for x in users if isinstance(x, dict) and x.get("id") == assignee_user_id and x.get("org_id") == org_id), None)
        if u is None:
            _audit("NOT_FOUND", None, org_id)
            return _err("NOT_FOUND", "Assignee user not found", assignee_user_id=assignee_user_id)
        if u.get("status") != "active" or not u.get("is_active", True):
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "Cannot assign issue to disabled/deleted user", assignee_user_id=assignee_user_id, user_status=u.get("status"))

    if parent_issue_id is not None:
        if parent_issue_id == issue_id:
            _audit("VALIDATION_ERROR", None, org_id)
            return _err("VALIDATION_ERROR", "parent_issue_id cannot equal issue_id")
        parent = next((x for x in issues if isinstance(x, dict) and x.get("id") == parent_issue_id), None)
        if parent is None:
            _audit("NOT_FOUND", None, org_id)
            return _err("NOT_FOUND", "parent_issue_id not found", parent_issue_id=parent_issue_id)
        if parent.get("org_id") != org_id:
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "Parent issue must be in the same organization", parent_issue_id=parent_issue_id)
        if parent.get("team_id") != issue.get("team_id"):
            _audit("CONFLICT", None, org_id)
            return _err("CONFLICT", "Parent and child must be in the same team", parent_issue_id=parent_issue_id)

    # Status lifecycle transitions for issue
    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "deleted": set()
    }

    now = _now_iso()
    actor_user_id = org_row.get("viewer_user_id") if isinstance(org_row.get("viewer_user_id"), str) else None

    history = issue.get("issue_history")
    if not isinstance(history, list):
        history = []
        issue["issue_history"] = history

    changed = False

    def _add_history(event_type, field_name=None, from_value=None, to_value=None):
        history.append({
            "id": _new_id("lin_hst_"),
            "issue_id": issue_id,
            "actor_user_id": actor_user_id,
            "event_type": event_type,
            "field_name": field_name,
            "from_value": from_value,
            "to_value": to_value,
            "created_at": now
        })

    # Apply changes with semantic history
    if title is not None and title.strip() != issue.get("title"):
        _add_history("updated", "title", issue.get("title"), title.strip())
        issue["title"] = title.strip()
        changed = True

    if description is not None and description != issue.get("description"):
        _add_history("updated", "description", issue.get("description"), description)
        issue["description"] = description
        changed = True

    if state_id is not None and state_id != issue.get("state_id"):
        _add_history("state_changed", "state_id", issue.get("state_id"), state_id)
        issue["state_id"] = state_id
        changed = True

    if priority is not None and priority != issue.get("priority"):
        _add_history("priority_changed", "priority", issue.get("priority"), priority)
        issue["priority"] = priority
        changed = True

    if estimate is not None:
        new_est = float(estimate)
        old_est = issue.get("estimate")
        if old_est is None or float(old_est) != new_est:
            _add_history("updated", "estimate", old_est, new_est)
            issue["estimate"] = new_est
            changed = True

    if assignee_user_id is not None:
        if assignee_user_id != issue.get("assignee_user_id"):
            if issue.get("assignee_user_id") is None and assignee_user_id is not None:
                _add_history("assigned", "assignee_user_id", None, assignee_user_id)
            elif assignee_user_id is None and issue.get("assignee_user_id") is not None:
                _add_history("unassigned", "assignee_user_id", issue.get("assignee_user_id"), None)
            else:
                _add_history("assigned", "assignee_user_id", issue.get("assignee_user_id"), assignee_user_id)
            issue["assignee_user_id"] = assignee_user_id
            changed = True

    if parent_issue_id is not None and parent_issue_id != issue.get("parent_issue_id"):
        _add_history("converted_to_subtask", "parent_issue_id", issue.get("parent_issue_id"), parent_issue_id)
        issue["parent_issue_id"] = parent_issue_id
        changed = True

    if due_date is not None and due_date != issue.get("due_date"):
        _add_history("updated", "due_date", issue.get("due_date"), due_date)
        issue["due_date"] = due_date
        changed = True

    if status is not None and status != issue.get("status"):
        cur = issue.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _audit("INVALID_TRANSITION", None, org_id)
            return _err("INVALID_TRANSITION", "Illegal issue status transition", from_status=cur, to_status=status)
        # special archive handling
        if status == "archived":
            issue["archived_at"] = now
            _add_history("archived", "status", cur, status)
        else:
            if cur == "archived" and status == "active":
                _add_history("updated", "status", cur, status)
            else:
                _add_history("updated", "status", cur, status)
            if status == "active":
                issue["archived_at"] = None
        issue["status"] = status
        changed = True

    if not changed:
        _audit("NOT_FOUND", None, org_id)
        return _err("NOT_FOUND", "No changes applied (fields identical or none provided)", issue_id=issue_id)

    issue["updated_at"] = now
    issues[idx] = issue
    _save("linear_issues.json", issues)
    _audit("OK", None, org_id, {"issue_id": issue_id})
    return {"issue": issue}

def linear_createComment(issue_id, author_user_id=None, body=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_createComment"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status_s, org_id=None, meta=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "lin_req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "org_id": org_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("linear_request_log.json", logs)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    if not isinstance(issue_id, str) or not issue_id.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "issue_id"})
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string", field="issue_id")
    if body is None or not isinstance(body, str):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "body"})
        return _err("VALIDATION_ERROR", "body is required and must be a string", field="body")
    if len(body) < 1 or len(body) > 20000:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "body"})
        return _err("VALIDATION_ERROR", "body length must be between 1 and 20000 characters", field="body")
    if author_user_id is not None and (not isinstance(author_user_id, str) or not author_user_id.strip()):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "author_user_id"})
        return _err("VALIDATION_ERROR", "author_user_id must be a non-empty string when provided", field="author_user_id")

    orgs = _load("linear_org.json")
    issues = _load("linear_issues.json")
    users = _load("linear_users.json")
    comments = _load("linear_comments.json")
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(issues, list):
        issues = []
    if not isinstance(users, list):
        users = []
    if not isinstance(comments, list):
        comments = []

    issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id), None)
    if not issue:
        active_org = next((o for o in orgs if isinstance(o, dict) and o.get("status") == "active"), None)
        _log("error", org_id=(active_org or {}).get("id"), meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    org_id = issue.get("org_id")
    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id and o.get("status") == "active"), None)
    if not org:
        _log("error", org_id=org_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    # Validate author if provided; default to viewer if not.
    if author_user_id is None:
        author_user_id = org.get("viewer_user_id")
    if author_user_id is not None:
        author = next((u for u in users if isinstance(u, dict) and u.get("id") == author_user_id and u.get("org_id") == org_id), None)
        if not author:
            _log("error", org_id=org_id, meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Author user not found", author_user_id=author_user_id)
        if author.get("status") in ("disabled", "deleted") or author.get("is_active") is False:
            _log("error", org_id=org_id, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "Author user is not active", author_user_id=author_user_id, status=author.get("status"))

    # Allow commenting even on archived issues (per rule: may be permitted); forbid only deleted
    if issue.get("status") == "deleted":
        _log("error", org_id=org_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Cannot comment on a deleted issue", issue_id=issue_id)

    now = _now()
    # Use an upstream-like comment id but ensure uniqueness within org
    linear_comment_id = _new_id("lin_cmt_up_")
    # Ensure unique(org_id, linear_comment_id)
    for _ in range(5):
        if any(isinstance(c, dict) and c.get("org_id") == org_id and c.get("linear_comment_id") == linear_comment_id for c in comments):
            linear_comment_id = _new_id("lin_cmt_up_")
        else:
            break
    if any(isinstance(c, dict) and c.get("org_id") == org_id and c.get("linear_comment_id") == linear_comment_id for c in comments):
        _log("error", org_id=org_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Could not allocate unique linear_comment_id")

    row = {
        "id": _new_id("lin_cmt_"),
        "org_id": org_id,
        "linear_comment_id": linear_comment_id,
        "issue_id": issue_id,
        "author_user_id": author_user_id,
        "body": body,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    comments.append(row)
    _save("linear_comments.json", comments)

    # Add issue history comment_created
    if not isinstance(issue.get("issue_history"), list):
        issue["issue_history"] = []
    issue["issue_history"].append({
        "id": _new_id("lin_hst_"),
        "issue_id": issue_id,
        "actor_user_id": author_user_id,
        "event_type": "comment_created",
        "field_name": None,
        "from_value": None,
        "to_value": {"comment_id": row["id"]},
        "created_at": now
    })
    issue["updated_at"] = now
    _save("linear_issues.json", issues)

    _log("ok", org_id=org_id)
    return {"comment": row}

