def linear_removeIssueLabel(issue_id, label_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, org_id=None, credential=None, detail=None, started=None):
        return

    started = time.time()

    if not isinstance(issue_id, str) or not issue_id.strip():
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string")
    if not isinstance(label_id, str) or not label_id.strip():
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "label_id must be a non-empty string")
    if not re.match(r"^lin_iss_[A-Za-z0-9]+$", issue_id):
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "issue_id is malformed")
    if not re.match(r"^lin_lbl_[A-Za-z0-9]+$", label_id):
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "label_id is malformed")

    orgs = _load("linear_org.json")
    users = _load("linear_users.json")
    workspaces = _load("linear_workspaces.json")
    issues = _load("linear_issues.json")

    issue_row = next((r for r in issues if r.get("id") == issue_id), None)
    if not issue_row:
        _log("error", started=started)
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    org_id = issue_row.get("org_id")
    org_row = next((o for o in orgs if o.get("id") == org_id), None)
    if not org_row or org_row.get("status") != "active":
        _log("error", org_id=org_id, started=started)
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    ws = next((w for w in workspaces if w.get("org_id") == org_id), None)
    if not ws:
        _log("error", org_id=org_id, started=started)
        return _err("UNAUTHORIZED", "Workspace data not available for organization")

    labels = ws.get("labels") or []
    # For remove, label must exist/visible in workspace even if archived? rule says "does not exist or not visible"
    label_exists = any(l.get("id") == label_id for l in labels)
    if not label_exists:
        _log("error", org_id=org_id, started=started)
        return _err("NOT_FOUND", "Label not found", label_id=label_id)

    if issue_row.get("status") == "archived":
        _log("error", org_id=org_id, started=started)
        return _err("CONFLICT", "Archived issues cannot be modified")
    if issue_row.get("status") == "deleted":
        _log("error", org_id=org_id, started=started)
        return _err("CONFLICT", "Deleted issues cannot be modified")

    joins = issue_row.get("issue_labels")
    if not isinstance(joins, list):
        joins = []
        issue_row["issue_labels"] = joins

    idx = None
    for i, j in enumerate(joins):
        if j.get("issue_id") == issue_id and j.get("label_id") == label_id:
            idx = i
            break

    if idx is None:
        _log("error", org_id=org_id, started=started)
        return _err("CONFLICT", "Label is not applied to issue", issue_id=issue_id, label_id=label_id)

    now = _now()
    # Hard delete join row (allowed by business rule)
    joins.pop(idx)

    actor_user_id = org_row.get("viewer_user_id")
    if actor_user_id and not any(u.get("id") == actor_user_id and u.get("org_id") == org_id for u in users):
        actor_user_id = None

    hist = issue_row.get("issue_history")
    if hist is None:
        hist = []
        issue_row["issue_history"] = hist
    import uuid
    hist.append(
        {
            "id": f"lin_hst_{uuid.uuid4().hex}",
            "issue_id": issue_id,
            "actor_user_id": actor_user_id,
            "event_type": "label_removed",
            "field_name": "labels",
            "from_value": {"label_id": label_id},
            "to_value": None,
            "created_at": now,
        }
    )

    issue_row["updated_at"] = now
    _save("linear_issues.json", issues)

    label_ids = {j.get("label_id") for j in issue_row.get("issue_labels") or []}
    resolved_labels = [l for l in labels if l.get("id") in label_ids and l.get("status") == "active"]

    _log("success", org_id=org_id, started=started)
    return {
        "issue": issue_row,
        "labels": resolved_labels,
    }

