def linear_subscribeToIssue(issue_id, user_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, org_id=None, credential=None, detail=None, started=None):
        return

    started = time.time()

    if not isinstance(issue_id, str) or not issue_id.strip():
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string")
    if not isinstance(user_id, str) or not user_id.strip():
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "user_id must be a non-empty string")
    if not re.match(r"^lin_iss_[A-Za-z0-9]+$", issue_id):
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "issue_id is malformed")
    if not re.match(r"^lin_usr_[A-Za-z0-9]+$", user_id):
        _log("error", started=started)
        return _err("VALIDATION_ERROR", "user_id is malformed")

    orgs = _load("linear_org.json")
    users = _load("linear_users.json")
    issues = _load("linear_issues.json")

    issue_row = next((r for r in issues if r.get("id") == issue_id), None)
    if not issue_row:
        _log("error", started=started)
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    org_id = issue_row.get("org_id")
    org_row = next((o for o in orgs if o.get("id") == org_id), None)
    if not org_row or org_row.get("status") != "active":
        _log("error", org_id=org_id, started=started)
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    user_row = next((u for u in users if u.get("id") == user_id and u.get("org_id") == org_id), None)
    if not user_row:
        _log("error", org_id=org_id, started=started)
        return _err("NOT_FOUND", "User not found", user_id=user_id)

    # Subscriptions cannot be changed for deleted issues; for archived, upstream often permits,
    # but business rule mentions "for example, ...": allow unless deleted.
    if issue_row.get("status") == "deleted":
        _log("error", org_id=org_id, started=started)
        return _err("CONFLICT", "Deleted issues cannot be modified", issue_id=issue_id)

    subs = issue_row.get("issue_subscriptions")
    if subs is None:
        subs = []
        issue_row["issue_subscriptions"] = subs

    existing = next((s for s in subs if s.get("issue_id") == issue_id and s.get("user_id") == user_id), None)
    now = _now()

    if existing:
        if existing.get("status") == "active":
            _log("error", org_id=org_id, started=started)
            return _err("CONFLICT", "User is already subscribed", issue_id=issue_id, user_id=user_id)
        # Upsert to active
        existing["status"] = "active"
        existing["updated_at"] = now
        # Preserve created_at
        if not existing.get("created_at"):
            existing["created_at"] = now
    else:
        subs.append(
            {
                "id": f"lin_sub_{uuid.uuid4().hex}",
                "issue_id": issue_id,
                "user_id": user_id,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
        )

    # Record history (comment_created exists, but subscription changes aren't enumerated).
    # Do not fabricate unsupported event types.

    issue_row["updated_at"] = now
    _save("linear_issues.json", issues)

    active_subs = [s for s in (issue_row.get("issue_subscriptions") or []) if s.get("status") == "active"]
    subscriber_ids = {s.get("user_id") for s in active_subs}
    resolved_subscribers = [u for u in users if u.get("id") in subscriber_ids and u.get("org_id") == org_id]

    _log("success", org_id=org_id, started=started)
    return {
        "issue_id": issue_id,
        "subscription": next((s for s in (issue_row.get("issue_subscriptions") or []) if s.get("user_id") == user_id), None),
        "subscribers": resolved_subscribers,
        "subscriptions": issue_row.get("issue_subscriptions") or [],
    }

