        return _err("VALIDATION_ERROR", "Self-relations are forbidden", field="related_issue_id")

    # Tool enum includes is_blocked_by; store uses blocked_by. Normalize.
    if not isinstance(relation_type, str) or relation_type not in ("blocks", "is_blocked_by", "relates_to", "duplicates"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "relation_type"})
