        "created_by_user_id": org.get("viewer_user_id"),
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    rels.append(relation)

    # For symmetric semantics, also store inverse where applicable.
    inverse_type = None
    if stored_type == "blocks":
        inverse_type = "blocked_by"
    elif stored_type == "blocked_by":
        inverse_type = "blocks"
    elif stored_type == "duplicates":
        inverse_type = "duplicated_by"
    elif stored_type == "duplicated_by":
        inverse_type = "duplicates"
    elif stored_type == "relates_to":
        inverse_type = "relates_to"

    if inverse_type:
        if not isinstance(b.get("issue_relations"), list):
            b["issue_relations"] = []
        brels = b["issue_relations"]
        inv_existing = next((r for r in brels if isinstance(r, dict) and r.get("from_issue_id") == related_issue_id and r.get("to_issue_id") == issue_id and r.get("type") == inverse_type and r.get("status") == "active"), None)
        if not inv_existing:
            brels.append({
                "id": _new_id("lin_rel_"),
                "from_issue_id": related_issue_id,
                "to_issue_id": issue_id,
                "type": inverse_type,
                "created_by_user_id": org.get("viewer_user_id"),
                "status": "active",
                "created_at": now,
                "updated_at": now
            })

    # history on source issue
    if not isinstance(a.get("issue_history"), list):
        a["issue_history"] = []
    a["issue_history"].append({
        "id": _new_id("lin_hst_"),
        "issue_id": issue_id,
        "actor_user_id": org.get("viewer_user_id"),
        "event_type": "relation_created",
        "field_name": "issue_relations",
        "from_value": None,
        "to_value": {"to_issue_id": related_issue_id, "type": stored_type},
        "created_at": now
    })
    a["updated_at"] = now
    b["updated_at"] = now

    _save("linear_issues.json", issues)
    _log("ok", org_id=org_id)
    return {"relation": relation}

