def linear_setIssuePriority(issue_id, priority, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_setIssuePriority"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, org_id=None, details=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"lin_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "org_id": org_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now(),
            "details": details or {}
        })
        _save("linear_request_log.json", logs)

    def _active_org():
        orgs = _load("linear_org.json")
        for o in orgs:
            if o.get("status") == "active":
                return o
        return None

    try:
        pat = re.compile(r"^lin_iss_[0-9A-HJKMNP-TV-Z]{16,}$")
        if not isinstance(issue_id, str) or not pat.match(issue_id):
            _log("error", details={"code": "VALIDATION_ERROR", "field": "issue_id"})
            return _err("VALIDATION_ERROR", "issue_id is missing/malformed", field="issue_id")
        if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
            _log("error", details={"code": "VALIDATION_ERROR", "field": "priority"})
            return _err("VALIDATION_ERROR", "priority must be one of 0,1,2,3,4", field="priority")

        org = _active_org()
        if not org:
            _log("error", details={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active Linear organization connection")

        issues = _load("linear_issues.json")
        if not isinstance(issues, list):
            issues = []

        issue = next((i for i in issues if i.get("id") == issue_id and i.get("org_id") == org.get("id") and i.get("status") != "deleted"), None)
        if not issue:
            _log("error", org_id=org.get("id"), details={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Issue not found")

        if issue.get("status") == "archived":
            _log("error", org_id=org.get("id"), details={"code": "CONFLICT"})
            return _err("CONFLICT", "Archived issues cannot be modified")

        if issue.get("status") != "active":
            _log("error", org_id=org.get("id"), details={"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Issue is not editable in its current status", status=issue.get("status"))

        old = issue.get("priority")
        if old == priority:
            # Idempotent success with real effect: still update updated_at? Real APIs often no-op but return same object.
            # We'll no-op but still return current issue; ensure not claiming a mutation count elsewhere.
            _log("ok", org_id=org.get("id"), details={"idempotent": True})
            return {"data": issue, "meta": {"org_id": org.get("id"), "idempotent": True}}

        now = _now()
        issue["priority"] = priority
        issue["updated_at"] = now

        hist = issue.get("issue_history")
        if not isinstance(hist, list):
            hist = []
            issue["issue_history"] = hist

        viewer_user_id = org.get("viewer_user_id")
        hist.append({
            "id": f"lin_hst_{int(time.time()*1000)}_{len(hist)+1}",
            "issue_id": issue.get("id"),
            "actor_user_id": viewer_user_id,
            "event_type": "priority_changed",
            "field_name": "priority",
            "from_value": old,
            "to_value": priority,
            "created_at": now
        })

        _save("linear_issues.json", issues)
        _log("ok", org_id=org.get("id"))
        return {"data": issue, "meta": {"org_id": org.get("id")}}
    except ValueError:
        _log("error", details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid input")
    except OSError:
        _log("error", details={"code": "CONFLICT"})
        return _err("CONFLICT", "Storage error")

