        # Fall back to parsing existing identifier prefix
        ident = src.get("identifier") or ""
        team_key = ident.split("-", 1)[0] if isinstance(ident, str) and "-" in ident else "ISSUE"

    # find next sequence in org for this team key
    max_n = 0
    for i in issues:
        if not isinstance(i, dict) or i.get("org_id") != org_id:
            continue
        ident = i.get("identifier")
        if not isinstance(ident, str):
            continue
        if ident.startswith(team_key + "-"):
            try:
                n = int(ident.split("-", 1)[1])
                if n > max_n:
                    max_n = n
            except Exception:
                pass
    new_identifier = f"{team_key}-{max_n + 1}"

    now = _now()
    new_issue_id = _new_id("lin_iss_")
    new_linear_issue_id = _new_id("lin_lin_")  # upstream placeholder, uniqueness per org
    for _ in range(5):
        if any(isinstance(i, dict) and i.get("org_id") == org_id and i.get("id") == new_issue_id for i in issues):
            new_issue_id = _new_id("lin_iss_")
        else:
            break

    if any(isinstance(i, dict) and i.get("org_id") == org_id and i.get("identifier") == new_identifier for i in issues):
        # extremely unlikely but handle
        new_identifier = f"{team_key}-{max_n + 2}"

    new_issue = {
        "id": new_issue_id,
        "org_id": org_id,
        "linear_issue_id": new_linear_issue_id,
        "identifier": new_identifier,
        "team_id": src.get("team_id"),
        "title": src.get("title"),
        "description": (src.get("description") if include_description else None),
        "state_id": src.get("state_id"),
        "priority": src.get("priority"),
        "estimate": src.get("estimate"),
        "assignee_user_id": None,
        "creator_user_id": org.get("viewer_user_id"),
        "parent_issue_id": None,
        "due_date": src.get("due_date"),
        "status": "active",
        "archived_at": None,
        "created_at": now,
        "updated_at": now,
        "issue_labels": [],
        "issue_subscriptions": [],
        "issue_relations": [],
        "issue_history": []
    }

    # Copy labels
    for j in (src.get("issue_labels") or []):
        if not isinstance(j, dict):
            continue
        lid = j.get("label_id")
        if not isinstance(lid, str):
            continue
        new_issue["issue_labels"].append({
            "id": _new_id("lin_ilb_"),
            "issue_id": new_issue_id,
            "label_id": lid,
            "created_at": now
        })

    # History: duplicated
    new_issue["issue_history"].append({
        "id": _new_id("lin_hst_"),
        "issue_id": new_issue_id,
        "actor_user_id": org.get("viewer_user_id"),
        "event_type": "duplicated",
        "field_name": None,
        "from_value": None,
        "to_value": {"source_issue_id": issue_id},
        "created_at": now
    })

    issues.append(new_issue)
    _save("linear_issues.json", issues)

    _log("ok", org_id=org_id)
    return {"issue": new_issue}

def linear_getIssueHistory(issue_id, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, org_id=None, viewer_user_id=None, meta=None, started=None):
        try:
            logs = _load("linear_request_log.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "lin_req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "status": status,
                "org_id": org_id,
                "viewer_user_id": viewer_user_id,
                "latency_ms": int((time.time() - started) * 1000) if started else None,
                "timestamp": _now(),
                "meta": meta or {},
            })
            _save("linear_request_log.json", logs)
        except Exception:
            pass

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            return off if off >= 0 else None
        except Exception:
            return None

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    started = time.time()
    endpoint = "linear_getIssueHistory"

    if not isinstance(issue_id, str) or not re.match(r"^lin_iss_[0-9A-HJKMNP-TV-Z]{16,}$", issue_id):
        out = _err("VALIDATION_ERROR", "issue_id is missing or malformed.", field="issue_id")
        _log(endpoint, "error", meta={"error": out["error"]}, started=started)
        return out

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        _log(endpoint, "error", meta={"error": out["error"]}, started=started)
        return out

    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_asc", "created_at_desc"):
        out = _err("VALIDATION_ERROR", "sort is invalid.", field="sort", allowed=["created_at_asc", "created_at_desc"])
        _log(endpoint, "error", meta={"error": out["error"]}, started=started)
        return out

    offset = _parse_cursor(cursor)
    if offset is None:
        out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        _log(endpoint, "error", meta={"error": out["error"]}, started=started)
        return out

    orgs = _load("linear_org.json")
    if not isinstance(orgs, list):
        orgs = []
    active_orgs = [o for o in orgs if isinstance(o, dict) and o.get("status") == "active"]
    if not active_orgs:
        out = _err("UNAUTHORIZED", "No active Linear organization connection is available.")
        _log(endpoint, "error", meta={"error": out["error"]}, started=started)
        return out

    issues = _load("linear_issues.json")
    if not isinstance(issues, list):
        issues = []

    workspaces = _load("linear_workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    issue = None
    org = None
    ws = None
    for o in active_orgs:
        cand = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id and i.get("org_id") == o.get("id")), None)
        if not cand:
            continue
        ws_cand = next((w for w in workspaces if isinstance(w, dict) and w.get("org_id") == o.get("id")), None)
        if not ws_cand:
            continue
        issue = cand
        org = o
        ws = ws_cand
        break

    if not issue:
        out = _err("NOT_FOUND", "Issue not found or not visible.", issue_id=issue_id)
        _log(endpoint, "error", meta={"error": out["error"]}, started=started)
        return out

    viewer_user_id = org.get("viewer_user_id")

    history = issue.get("issue_history")
    if not isinstance(history, list):
        history = []

    def _dt(v):
        if not isinstance(v, str):
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    history_sorted = sorted(
        [h for h in history if isinstance(h, dict) and h.get("issue_id") == issue_id],
        key=lambda h: (_dt(h.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(h.get("id") or "")),
        reverse=(sort == "created_at_desc")
    )

    total = len(history_sorted)
    page = history_sorted[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _make_cursor(next_offset) if has_more else None

    resp = {
        "history": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }
    _log(endpoint, "ok", org_id=org.get("id"), viewer_user_id=viewer_user_id, started=started)
    return resp

def linear_getComments(issue_id, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "linear_getComments"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status_s, org_id=None, meta=None):
        logs = _load("linear_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "lin_req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "org_id": org_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("linear_request_log.json", logs)

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("offset:"):
                off = int(s.split(":", 1)[1])
                return off if off >= 0 else None
            return 0
        except Exception:
            return 0

    def _make_cursor(off):
        return base64.urlsafe_b64encode(f"offset:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    if not isinstance(issue_id, str) or not issue_id.strip():
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "issue_id"})
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string", field="issue_id")
    if status is not None and status not in ("active", "edited", "deleted"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "status"})
        return _err("VALIDATION_ERROR", "status is invalid", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_asc", "created_at_desc"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "sort"})
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    off = _parse_cursor(cursor)
    if off is None:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    orgs = _load("linear_org.json")
    issues = _load("linear_issues.json")
    comments = _load("linear_comments.json")
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(issues, list):
        issues = []
    if not isinstance(comments, list):
        comments = []

    issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id), None)
    if not issue:
        active_org = next((o for o in orgs if isinstance(o, dict) and o.get("status") == "active"), None)
        _log("error", org_id=(active_org or {}).get("id"), meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    org_id = issue.get("org_id")
    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id and o.get("status") == "active"), None)
    if not org:
        _log("error", org_id=org_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Linear organization connection is not active")

    rows = [c for c in comments if isinstance(c, dict) and c.get("org_id") == org_id and c.get("issue_id") == issue_id]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    reverse = (sort == "created_at_desc")
    rows_sorted = sorted(rows, key=lambda c: _dt(c.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=reverse)

    total = len(rows_sorted)
    page = rows_sorted[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log("ok", org_id=org_id, meta={"total": total})
    return {
        "comments": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def linear_getAuthStatus(org_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0530000" if __import__("os").path.isdir("./environment_mix/0530000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ensure_request_log():
        path = os.path.join(_DB, "request_log.json")
        if not os.path.exists(path):
            _save("request_log.json", [])
        return "request_log.json"

    def _log_request(endpoint, scoped_org_id, status, latency_ms, credential_id=None, error_code=None):
        fname = _ensure_request_log()
        logs = _load(fname)
        logs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "org_id": scoped_org_id,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int(latency_ms),
                "created_at": _now(),
            }
        )
        _save(fname, logs)

    def _rate_limit_check(endpoint, scoped_org_id):
        # Simple per-org fixed-window limiter enforced via request_log.
        # If no log exists yet, it is created.
        fname = _ensure_request_log()
        logs = _load(fname)

        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit = 120  # requests per org per minute
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in reversed(logs):
            if r.get("org_id") != scoped_org_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
        if cnt >= limit:
            reset_in = int((cutoff + datetime.timedelta(seconds=window_s) - now).total_seconds())
            if reset_in < 0:
                reset_in = 0
            return False, {"limit": limit, "window_seconds": window_s, "used": cnt, "remaining": 0, "reset_in_seconds": reset_in}
        remaining = max(0, limit - cnt)
        return True, {"limit": limit, "window_seconds": window_s, "used": cnt, "remaining": remaining, "reset_in_seconds": window_s}

    def _quota_check(scoped_org_id):
        # Daily per-org quota enforced via request_log.
        fname = _ensure_request_log()
        logs = _load(fname)
        now = datetime.datetime.now(datetime.timezone.utc)
        start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        limit = 5000  # requests per org per day
        used = 0
        for r in logs:
            if r.get("org_id") != scoped_org_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= start:
                used += 1
        if used >= limit:
            return False, {"limit": limit, "used": used, "remaining": 0, "period": "day", "reset_at": (start + datetime.timedelta(days=1)).isoformat()}
        return True, {"limit": limit, "used": used, "remaining": max(0, limit - used), "period": "day", "reset_at": (start + datetime.timedelta(days=1)).isoformat()}

    t0 = time.time()
    endpoint = "linear_getAuthStatus"

    # Validate input
    if not isinstance(org_id, str):
        latency_ms = (time.time() - t0) * 1000
        _log_request(endpoint, None, "error", latency_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "org_id must be a string")
    if not re.match(r"^lin_org_[0-9A-HJKMNP-TV-Z]{16,}$", org_id):
        latency_ms = (time.time() - t0) * 1000
        _log_request(endpoint, org_id, "error", latency_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "org_id is invalid", field="org_id")

    # Rate/quota enforcement (counts all calls, including this one based on prior records)
    ok_rl, rl = _rate_limit_check(endpoint, org_id)
    if not ok_rl:
        latency_ms = (time.time() - t0) * 1000
        _log_request(endpoint, org_id, "error", latency_ms, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", rate_limit=rl)
    ok_q, q = _quota_check(org_id)
    if not ok_q:
        latency_ms = (time.time() - t0) * 1000
        _log_request(endpoint, org_id, "error", latency_ms, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Quota exceeded", quota=q)

    orgs = _load("linear_org.json")
    org = None
    for o in orgs:
        if o.get("id") == org_id:
            org = o
            break
    if not org:
        latency_ms = (time.time() - t0) * 1000
        _log_request(endpoint, org_id, "error", latency_ms, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Organization not found", org_id=org_id)

    # Must scope by a single active org
    if org.get("status") != "active":
        latency_ms = (time.time() - t0) * 1000
        _log_request(endpoint, org_id, "error", latency_ms, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Organization connection is not active", org_status=org.get("status"))

    users = _load("linear_users.json")
    viewer = None
    viewer_id = org.get("viewer_user_id")

    if viewer_id:
        for u in users:
            if u.get("id") == viewer_id and u.get("org_id") == org_id:
                viewer = u
                break

    # If viewer_user_id is null or invalid, resolve/create a viewer user and set viewer_user_id
    mutated = False
    if viewer is None:
        # Prefer an active user in this org; otherwise create a minimal viewer.
        candidate = None
        for u in users:
            if u.get("org_id") == org_id and u.get("status") == "active" and u.get("is_active") is True:
                candidate = u
                break
        if candidate is None:
            new_id = "lin_usr_" + uuid.uuid4().hex[:20]
            now = _now()
            candidate = {
                "id": new_id,
                "org_id": org_id,
                "linear_user_id": "lin_up_usr_" + uuid.uuid4().hex[:16],
                "display_name": "Viewer",
                "email": None,
                "is_active": True,
                "is_admin": True,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            users.append(candidate)
            _save("linear_users.json", users)

        viewer = candidate
        for o in orgs:
            if o.get("id") == org_id:
                o["viewer_user_id"] = viewer.get("id")
                o["updated_at"] = _now()
                mutated = True
                break
        if mutated:
            _save("linear_org.json", orgs)

    # Derive scopes (no explicit permissions store; infer from viewer flags)
    scopes = ["read"]
    if viewer and viewer.get("is_admin") is True:
        scopes.append("admin")
        scopes.append("write")

    # Recompute current rate/quota after prior checks (still based on persisted history)
    # Note: this call itself is logged at the end.
    ok_rl2, rl2 = _rate_limit_check(endpoint, org_id)
    ok_q2, q2 = _quota_check(org_id)

    body = {
        "organization": {
            "id": org.get("id"),
            "linear_org_id": org.get("linear_org_id"),
            "name": org.get("name"),
            "url_key": org.get("url_key"),
            "status": org.get("status"),
        },
        "viewer": viewer,
        "scopes": scopes,
        "rate_limit": rl2 if ok_rl2 else rl,
        "quota": q2 if ok_q2 else q,
        "connected": True,
    }

    latency_ms = (time.time() - t0) * 1000
    _log_request(endpoint, org_id, "ok", latency_ms, credential_id=viewer.get("id") if isinstance(viewer, dict) else None)
    return {"data": body}
